/* Kelas VII — Semester 2 — Kisah Ketabahan Nabi Ayyub & Keluarga Nabi Yakub — 50 soal */
window.BSRegister({
'id':'k7-kisah-sabar','grade':7,'semester':2,'order':10,
'title':'Kisah Ketabahan Nabi Ayyub & Keluarga Nabi Yakub',
'desc':'Kisah ketabahan Nabi Ayyub dalam menghadapi ujian penyakit dan kehilangan harta, kisah keluarga Nabi Yakub dan Nabi Yusuf, makna sabar dan macam-macamnya, serta keteladanan yang dapat diterapkan dalam kehidupan.',
'kd':'Menganalisis kisah ketabahan Nabi Ayyub AS dan keluarga Nabi Yakub AS, serta menampilkan perilaku sabar sebagai implementasi dari pemahaman terhadap kisah tersebut.',
'questions':[{level:'HOTS',indicator:'Menentukan pokok ujian yang dialami Nabi Ayyub',text:'Ujian yang dialami Nabi Ayyub sebagaimana disebut dalam Al-Quran mencakup ...',options:['cobaan berupa fitnah dari kaumnya sehingga ia dipenjara','cobaan berupa kekeringan panjang yang melanda negerinya','kehilangan jabatan dan diusir dari negerinya','cobaan penyakit lama, kehilangan harta, dan kehilangan anak'],answer:3,explanation:'Q.S. Shad [38]: 41 menceritakan bahwa Ayyub diserang oleh setan dengan kepayahan dan azab, dan Q.S. Shad [38]: 44 menyebut bahwa Allah mendapati Ayyub sebagai orang yang sabar dan sebaik-baik hamba yang senantiasa kembali kepada Allah. Q.S. al-Anbiya [21]: 83-84 mencatat doa Ayyub bahwa ia ditimpa bahaya dan Allah adalah Tuhan Yang Maha Penyayang, lalu Allah memperkenankan doanya, menghilangkan bahaya yang menimpanya, serta mengembalikan keluarganya dan yang sebanyak itu bersama mereka sebagai rahmat dan peringatan bagi orang yang beribadah. Para mufasir menjelaskan bahwa ujian Ayyub meliputi penyakit yang lama pada badannya, hilangnya harta, dan wafatnya anak-anaknya, tetapi ia tetap bersyukur dan tidak mengeluh.'},
{level:'HOTS',indicator:'Menganalisis sikap Nabi Ayyub ketika ditimpa penyakit lama',text:'Nabi Ayyub menderita penyakit dalam waktu yang sangat lama sehingga sebagian orang menjauhinya, tetapi ia tetap bersyukur dan tidak mengeluh kepada Allah. Analisis yang paling tepat terhadap sikap tersebut adalah ...',options:['sikap itu berarti Ayyub pasrah tanpa berobat','sikap itu hanya dapat dilakukan oleh seorang nabi sehingga tidak ada pelajaran bagi umat','sikap itu menunjukkan bahwa Ayyub tidak merasakan penderitaan','mengarahkan keluhan hanya kepada Allah dan tetap beribadah'],answer:3,explanation:'Q.S. al-Anbiya [21]: 83 mencatat doa Ayyub bahwa ia ditimpa bahaya dan Allah adalah Tuhan Yang Maha Penyayang, yang menunjukkan bahwa ia mengadukan keadaannya kepada Allah dengan bahasa yang penuh adab tanpa menyalahkan ketentuan Allah. Q.S. Shad [38]: 44 menyebut pujian Allah bahwa Ayyub merupakan orang yang sabar dan sebaik-baik hamba yang senantiasa kembali kepada Allah. Q.S. al-Baqarah [2]: 155-157 menyebut bahwa ujian merupakan ketentuan dan memberi kabar gembira bagi orang yang sabar. Hadis menyebut bahwa besarnya balasan sesuai dengan besarnya ujian dan bahwa Allah apabila mencintai suatu kaum maka Dia menguji mereka. Q.S. Yusuf [12]: 86 mencatat ucapan Nabi Yakub bahwa ia hanya mengadukan kesusahan dan kesedihannya kepada Allah, yang merupakan teladan serupa.'},
{level:'HOTS',indicator:'Menentukan bentuk penggantian nikmat bagi Nabi Ayyub',text:'Allah memulihkan keadaan Nabi Ayyub setelah ujian yang panjang. Bentuk pemulihan yang paling tepat sesuai dalil adalah ...',options:['disembuhkan melalui mata air lalu keluarganya dikembalikan dan ditambah','Allah memindahkan Ayyub ke negeri lain yang lebih baik dan memberinya keluarga baru','Allah mengembalikan kesehatannya tetapi tidak mengembalikan keluarganya','Allah mengembalikan hartanya berlipat ganda tetapi membiarkan penyakitnya sebagai tanda kesabaran'],answer:0,explanation:'Q.S. Shad [38]: 42 berisi perintah Allah kepada Ayyub untuk menghentakkan kakinya sehingga keluar air yang sejuk untuk mandi dan minum, dan Q.S. Shad [38]: 43 menyebut bahwa Allah menganugerahkan kepadanya keluarganya dan yang sebanyak itu bersama mereka sebagai rahmat dari Allah dan peringatan bagi orang-orang yang berakal. Q.S. al-Anbiya [21]: 84 menyebut bahwa Allah memperkenankan doa Ayyub lalu menghilangkan bahaya yang menimpanya dan mengembalikan keluarganya serta yang sebanyak itu bersama mereka sebagai rahmat dari sisi Allah dan peringatan bagi orang-orang yang beribadah. Hadis juga menyebut bahwa Ayyub ketika sedang mandi tiba-tiba jatuh kepadanya belalang emas lalu ia mengumpulkan pakaiannya dan Allah menegurnya, lalu Ayyub menjawab bahwa ia tidak dapat meninggalkan keberkahan Tuhan. Karena itu pemulihan itu menyeluruh mencakup kesehatan, keluarga, dan harta.'},
{level:'HOTS',indicator:'Menganalisis hikmah sumpah Nabi Ayyub terhadap istrinya',text:'Dalam kisahnya disebut bahwa Nabi Ayyub pernah bersumpah akan memukul istrinya sejumlah hitungan tertentu karena suatu perkara, lalu Allah memberi jalan keluar. Analisis yang paling tepat terhadap hikmah jalan keluar tersebut adalah ...',options:['jalan keluar itu menunjukkan bahwa sumpah tidak perlu dipenuhi','jalan keluar itu berarti sumpah yang sudah diucapkan dapat dibatalkan tanpa kafarat','memukul dengan seikat rumput sekali sehingga sumpah terpenuhi','jalan keluar itu hanya berlaku bagi para nabi sehingga tidak ada pelajaran bagi umat'],answer:2,explanation:'Q.S. Shad [38]: 44 berisi perintah Allah kepada Ayyub untuk mengambil dengan tangan seikat rumput lalu memukulkannya dan tidak melanggar sumpah, dan ayat itu dilanjutkan dengan pujian bahwa Allah mendapati Ayyub sebagai orang yang sabar dan sebaik-baik hamba yang senantiasa kembali kepada Allah. Para mufasir menjelaskan bahwa jalan keluar itu diberikan karena istri Ayyub telah berkhidmat dan bersabar mendampingi suaminya selama masa ujian yang panjang, sehingga tidak pantas disakiti. Ketentuan ini menjadi dasar dalam fikih tentang pelaksanaan hukuman terhadap orang yang lemah dengan cara yang tidak membahayakan. Q.S. al-Baqarah [2]: 185 menyebut bahwa Allah menghendaki kemudahan dan tidak menghendaki kesukaran. Hadis juga menyebut bahwa agama ini mudah.'},
{level:'HOTS',indicator:'Menentukan keteladanan Nabi Ayyub bagi pelajar yang sakit',text:'Keteladanan Nabi Ayyub yang paling tepat untuk diterapkan oleh seorang pelajar yang sedang sakit dalam waktu lama adalah ...',options:['mengeluh kepada seluruh teman agar memperoleh simpati','berhenti berdoa karena doa belum dikabulkan','berhenti belajar karena sakit merupakan tanda untuk berhenti','tetap beribadah dan belajar sesuai kemampuan serta berobat'],answer:3,explanation:'Q.S. al-Anbiya [21]: 83-84 menggambarkan Ayyub yang berdoa lalu diperkenankan dan dipulihkan, yang menjadi teladan bahwa doa merupakan sarana utama ketika tertimpa ujian. Q.S. al-Baqarah [2]: 286 menegaskan bahwa Allah tidak membebani seseorang melainkan sesuai kesanggupannya, sehingga belajar tetap dapat dilakukan dengan cara yang memungkinkan. Hadis menyebut bahwa tidak ada suatu musibah pun yang menimpa seorang muslim melainkan Allah menghapus dosa-dosanya karena musibah itu walaupun hanya duri yang menusuknya. Hadis juga menyebut bahwa Allah tidak menurunkan penyakit melainkan menurunkan pula obatnya, sehingga berobat merupakan bagian dari ikhtiar. Q.S. Yusuf [12]: 87 melarang berputus asa dari rahmat Allah. Karena itu berhenti belajar, mengeluh yang menunjukkan ketidakridaan, dan berhenti berdoa bukan teladan Nabi Ayyub.'},
{level:'HOTS',indicator:'Menganalisis kedudukan Nabi Yusuf dalam kisah keluarga Nabi Yakub',text:'Kisah keluarga Nabi Yakub berpusat pada peristiwa Nabi Yusuf yang dibuang oleh saudara-saudaranya lalu menjadi pejabat di Mesir. Analisis yang paling tepat terhadap kedudukan kisah tersebut adalah ...',options:['kisah itu merupakan kisah sejarah tanpa ketentuan hukum yang dapat diambil','kisah itu hanya relevan bagi keluarga yang memiliki banyak anak','mengandung pelajaran lengkap tentang kesabaran dan akhlak memaafkan','kisah itu merupakan kisah tentang persaingan antar saudara tanpa pesan keagamaan'],answer:2,explanation:'Q.S. Yusuf [12]: 3 menyebut bahwa Allah menceritakan kepada Nabi Muhammad sebaik-baik kisah melalui wahyu Al-Quran padahal sebelumnya beliau termasuk orang yang tidak mengetahui. Q.S. Yusuf [12]: 111 menyebut bahwa pada kisah mereka terdapat pelajaran bagi orang-orang yang berakal. Kisah Yusuf mencakup seluruh aspek tersebut yaitu kesabaran Nabi Yakub ketika kehilangan Yusuf sebagaimana Q.S. Yusuf [12]: 18, bahaya hasad saudara-saudaranya sebagaimana Q.S. Yusuf [12]: 8, penjagaan Yusuf dari godaan istri pejabat sebagaimana Q.S. Yusuf [12]: 24, kesabaran dalam penjara sebagaimana Q.S. Yusuf [12]: 33, kenaikan derajat sebagaimana Q.S. Yusuf [12]: 54, serta puncak akhlak memaafkan sebagaimana Q.S. Yusuf [12]: 92.'},
{level:'HOTS',indicator:'Menentukan sebab saudara-saudara Yusuf membenci Yusuf',text:'Sebab saudara-saudara Yusuf merencanakan untuk membuang Yusuf adalah ...',options:['Yusuf pernah berbuat salah kepada mereka sehingga mereka membalas','mereka diperintahkan oleh ibu mereka untuk membuang Yusuf','hasad karena merasa ayah mereka lebih mencintai Yusuf','Yusuf memiliki kekayaan yang mereka inginkan sehingga mereka mengambilnya'],answer:2,explanation:'Q.S. Yusuf [12]: 8 mencatat ucapan saudara-saudara Yusuf bahwa Yusuf dan saudaranya lebih dicintai oleh ayah mereka daripada mereka padahal golongan mereka lebih kuat, dan bahwa ayah mereka berada dalam kekeliruan yang nyata. Q.S. Yusuf [12]: 9 mencatat rencana mereka untuk membunuh Yusuf atau membuangnya ke suatu daerah agar perhatian ayah mereka beralih kepada mereka dan setelah itu mereka menjadi orang yang baik. Q.S. Yusuf [12]: 10 mencatat usulan salah seorang di antara mereka agar tidak membunuhnya melainkan melemparkannya ke dasar sumur agar dipungut oleh musafir. Hadis menyebut bahwa hasad memakan kebaikan sebagaimana api memakan kayu bakar. Karena itu hasad merupakan sebab utama perbuatan tersebut dan merupakan penyakit hati yang berbahaya.'},
{level:'HOTS',indicator:'Menganalisis sikap Nabi Yakub ketika menerima kabar palsu tentang Yusuf',text:'Saudara-saudara Yusuf pulang membawa baju yang berlumur darah palsu dan mengatakan bahwa Yusuf dimakan serigala. Analisis yang paling tepat terhadap sikap Nabi Yakub adalah ...',options:['Yakub mengusir seluruh anaknya karena telah berdusta','Yakub langsung mempercayai kabar itu karena terdapat bukti baju','Yakub mencari Yusuf sendiri tanpa memberitahu siapa pun','bajunya utuh sehingga tidak mungkin dimakan serigala'],answer:3,explanation:'Q.S. Yusuf [12]: 18 mencatat ucapan Yakub bahwa sebenarnya diri mereka sendirilah yang memandang baik perbuatan yang buruk itu, maka kesabaran yang indah itulah kesabaran yang baik, dan kepada Allah saja memohon pertolongan terhadap apa yang mereka ceritakan. Para mufasir menjelaskan bahwa Yakub mengetahui dusta mereka karena baju Yusuf tidak sobek padahal mereka mengatakan dimakan serigala. Q.S. Yusuf [12]: 86 mencatat ucapan Yakub bahwa ia hanya mengadukan kesusahan dan kesedihannya kepada Allah dan mengetahui dari Allah apa yang tidak mereka ketahui. Q.S. Yusuf [12]: 87 juga mencatat perintah Yakub kepada anak-anaknya agar mencari berita tentang Yusuf dan tidak berputus asa dari rahmat Allah. Karena itu sikap Yakub merupakan teladan kesabaran yang tidak disertai keputusasaan.'},
{level:'HOTS',indicator:'Menentukan makna sabar yang indah',text:'Nabi Yakub menyatakan bahwa kesabaran yang indah itulah kesabaran yang baik. Makna sabar yang indah yang paling tepat adalah ...',options:['kesabaran yang berarti tidak merasakan kesedihan sama sekali','kesabaran yang berlangsung singkat karena ujian akan segera berakhir','kesabaran yang ditunjukkan kepada orang lain agar memperoleh pujian','sabar tanpa mengeluh kepada makhluk dan tanpa meratap'],answer:3,explanation:'Q.S. Yusuf [12]: 18 mencatat ucapan Yakub bahwa kesabaran yang indah itulah kesabaran yang baik, dan Q.S. Yusuf [12]: 83 mencatat ucapan serupa ketika Bunyamin ditahan di Mesir. Hadis menyebut bahwa kesabaran itu pada pukulan pertama, yang berarti kesabaran yang paling bernilai adalah ketika musibah baru menimpa. Q.S. al-Baqarah [2]: 155-157 menyebut bahwa orang sabar adalah yang ketika tertimpa musibah mengucapkan bahwa mereka milik Allah dan kepada-Nya kembali. Hadis melarang meratap, memukul pipi, dan merobek pakaian ketika tertimpa musibah. Q.S. Yusuf [12]: 86 menunjukkan bahwa mengadukan kesedihan kepada Allah bukan termasuk keluhan yang tercela karena merupakan bentuk doa. Karena itu sabar yang indah merupakan kesabaran batin yang disertai adab lahir dan keyakinan kepada pertolongan Allah.'},
{level:'HOTS',indicator:'Menganalisis ujian Yusuf ketika digoda oleh istri pejabat',text:'Nabi Yusuf tinggal di rumah seorang pejabat Mesir dan digoda oleh istri pejabat tersebut. Analisis yang paling tepat terhadap sikap Yusuf adalah ...',options:['Yusuf menolak karena belum mengenal perempuan tersebut','Yusuf menolak karena rencana saudaranya belum selesai sehingga ia harus bertahan','Yusuf menolak karena takut kepada hukuman pejabat tersebut','menolak karena sadar nikmat Allah, pengawasan-Nya, dan amanah tuannya'],answer:3,explanation:'Q.S. Yusuf [12]: 23-24 menceritakan bahwa perempuan yang di rumah Yusuf tinggal itu menggodanya dan menutup pintu-pintu lalu mengajak Yusuf, dan Yusuf menjawab aku berlindung kepada Allah, sungguh tuanku telah memperlakukan aku dengan baik, dan sesungguhnya orang yang zalim tidak akan beruntung, lalu ayat itu menyebut bahwa perempuan itu telah berkehendak kepadanya dan Yusuf pun berkehendak kepadanya seandainya ia tidak melihat bukti dari Tuhannya, dan demikianlah Allah memalingkan dari padanya keburukan dan kekejian karena sesungguhnya ia termasuk hamba-hamba yang terpilih. Q.S. Yusuf [12]: 25 menceritakan keduanya berlomba menuju pintu. Hadis menyebut bahwa salah satu golongan yang dinaungi Allah adalah laki-laki yang diajak oleh perempuan berkedudukan dan cantik lalu berkata aku takut kepada Allah.'},
{level:'HOTS',indicator:'Menentukan sikap Yusuf ketika dipenjara tanpa kesalahan',text:'Nabi Yusuf memilih dipenjara daripada memenuhi ajakan yang melanggar ketentuan Allah. Sikap yang paling tepat untuk diteladani dari pilihan tersebut adalah ...',options:['memilih dipenjara agar terhindar dari fitnah masyarakat','memilih penjara daripada dosa dan berdakwah di dalamnya','memilih dipenjara karena tidak ada jalan lain','memilih dipenjara sambil menunggu pertolongan tanpa melakukan apa pun'],answer:1,explanation:'Q.S. Yusuf [12]: 33 mencatat doa Yusuf bahwa wahai Tuhanku penjara lebih aku sukai daripada memenuhi ajakan mereka kepadaku, dan jika Engkau tidak hindarkan dariku tipu daya mereka tentu aku akan cenderung untuk memenuhi keinginan mereka dan tentulah aku termasuk orang-orang yang bodoh. Q.S. Yusuf [12]: 34 menyebut bahwa Tuhannya memperkenankan doa Yusuf dan memalingkan tipu daya mereka. Q.S. Yusuf [12]: 37-40 menceritakan bahwa Yusuf di penjara menyampaikan dakwah kepada kedua temannya dengan menjelaskan bahwa ia meninggalkan agama orang yang tidak beriman kepada Allah dan mengajak kepada ibadah hanya kepada Allah. Hadis juga menyebut bahwa orang yang beramal di tempat yang sulit memperoleh pahala yang besar. Karena itu memilih penjara daripada dosa merupakan teladan mendahulukan keselamatan akhirat.'},
{level:'HOTS',indicator:'Menganalisis hikmah Yusuf tetap berada di penjara beberapa tahun',text:'Nabi Yusuf tetap berada di penjara beberapa tahun walaupun telah terbukti tidak bersalah karena teman yang dibebaskan lupa menyampaikan perkara Yusuf kepada raja. Analisis yang paling tepat terhadap hikmah kenyataan tersebut adalah ...',options:['masa penjara itu menyiapkan kedudukan Yusuf yang terbukti kemampuannya','hal itu berarti orang yang tidak bersalah akan selalu dipenjara','hal itu terjadi karena Yusuf tidak cukup berusaha menyampaikan perkaranya','hal itu menunjukkan bahwa usaha Yusuf tidak berguna'],answer:0,explanation:'Q.S. Yusuf [12]: 42 mencatat bahwa Yusuf berkata kepada orang yang diketahuinya akan bebas di antara keduanya agar menyebutkan hal ihwalnya kepada tuannya, lalu setan menjadikan orang itu lupa menyebutkannya sehingga Yusuf tetap dalam penjara beberapa tahun. Q.S. Yusuf [12]: 43-49 menceritakan mimpi raja yang tidak dapat ditafsirkan oleh para pembesarnya, lalu orang yang pernah dibebaskan itu teringat kepada Yusuf. Q.S. Yusuf [12]: 50-54 menceritakan raja memerintahkan memeriksa perkara Yusuf, perempuan-perempuan mengakui kebenaran Yusuf, dan Yusuf diangkat menjadi bendahara negeri. Q.S. Yusuf [12]: 56 menyebut bahwa Allah memberi kedudukan kepada siapa yang dikehendaki-Nya. Karena itu keterlambatan itu merupakan bagian dari rencana Allah yang menghasilkan kedudukan yang lebih kokoh.'},
{level:'HOTS',indicator:'Menentukan puncak akhlak Yusuf ketika bertemu saudara-saudaranya',text:'Ketika saudara-saudara Yusuf datang ke Mesir dalam keadaan membutuhkan dan tidak mengenali Yusuf, Yusuf mampu membalas perbuatan mereka. Puncak akhlak Yusuf yang paling tepat adalah ...',options:['membalas perbuatan mereka agar mereka merasakan penderitaan yang pernah ia alami','menyuruh mereka pulang tanpa memberi bantuan agar mereka menyadari kesalahannya','menghukum sebagian dari mereka sebagai peringatan bagi yang lain','memaafkan tanpa mengungkit dan menisbatkan perbuatan itu kepada setan'],answer:3,explanation:'Q.S. Yusuf [12]: 92 mencatat ucapan Yusuf kepada saudara-saudaranya bahwa pada hari ini tidak ada cercaan terhadap kalian, mudah-mudahan Allah mengampuni kalian dan Dia Maha Penyayang di antara para penyayang. Q.S. Yusuf [12]: 100 mencatat ucapan Yusuf kepada ayah dan ibunya bahwa ini merupakan tafsir mimpinya dahulu dan bahwa Allah telah berbuat baik kepadanya ketika mengeluarkannya dari penjara dan membawa mereka dari dusun setelah setan merusak hubungan antara dia dan saudara-saudaranya. Q.S. Yusuf [12]: 90 mencatat ucapan saudara-saudaranya yang menyadari bahwa Allah telah melebihkan Yusuf atas mereka. Hadis menyebut bahwa tidak ada yang memaafkan melainkan Allah menambah kemuliaannya. Karena itu puncak akhlak Yusuf adalah memaafkan tanpa mengungkit dan menisbatkan kerusakan kepada setan untuk menjaga kehormatan saudara-saudaranya.'},
{level:'HOTS',indicator:'Menganalisis ketabahan Nabi Yakub selama kehilangan Yusuf',text:'Nabi Yakub kehilangan Yusuf selama puluhan tahun tetapi tetap berharap kepada Allah dan melarang anak-anaknya berputus asa. Analisis yang paling tepat terhadap ketabahan tersebut adalah ...',options:['ketabahan itu hanya dapat dilakukan oleh seorang nabi sehingga tidak ada pelajaran bagi umat','ketabahan itu berarti Yakub menolak kenyataan bahwa Yusuf telah tiada','kesabaran disertai harapan dan larangan berputus asa dari rahmat Allah','ketabahan itu berarti Yakub tidak merasakan kesedihan'],answer:2,explanation:'Q.S. Yusuf [12]: 86 mencatat ucapan Yakub bahwa sesungguhnya hanyalah kepada Allah aku mengadukan kesusahan dan kesedihanku, dan aku mengetahui dari Allah apa yang kamu tidak mengetahuinya. Q.S. Yusuf [12]: 87 mencatat perintah Yakub kepada anak-anaknya agar pergi mencari berita tentang Yusuf dan saudaranya serta jangan berputus asa dari rahmat Allah karena sesungguhnya tidak berputus asa dari rahmat Allah melainkan kaum yang kafir. Q.S. Yusuf [12]: 84 menyebut bahwa mata Yakub menjadi putih karena kesedihan yang mendalam sehingga ia menahan amarah, yang menunjukkan bahwa kesedihan itu nyata tetapi tetap terkendali. Hadis menyebut bahwa Allah sesuai dengan prasangka hamba-Nya. Karena itu ketabahan Yakub merupakan kesabaran yang disertai harapan dan pencarian, bukan penolakan terhadap kenyataan.'},
{level:'HOTS',indicator:'Menentukan pelajaran dari kisah keluarga Nabi Yakub tentang hasad',text:'Pelajaran yang paling tepat dari perbuatan saudara-saudara Yusuf terhadap hubungan antar saudara adalah ...',options:['hasad antar saudara harus diobati dan orang tua berlaku adil','kecintaan orang tua kepada salah satu anak pasti menimbulkan masalah sehingga harus dihindari','hasad tidak berbahaya karena hanya berupa perasaan dalam hati','persaingan antar saudara merupakan hal yang wajar sehingga tidak perlu diwaspadai'],answer:0,explanation:'Q.S. Yusuf [12]: 8-9 mencatat bahwa hasad timbul dari perasaan bahwa Yusuf dan saudaranya lebih dicintai oleh ayah mereka, dan hasad itu mendorong rencana untuk membunuh atau membuang Yusuf. Q.S. an-Nisa [4]: 32 melarang mengangan-angankan kelebihan yang diberikan Allah kepada sebagian orang atas sebagian yang lain. Hadis menyebut bahwa hasad memakan kebaikan sebagaimana api memakan kayu bakar. Hadis juga menyebut bahwa Rasulullah memerintahkan berlaku adil di antara anak-anak dalam pemberian. Hadis lain menyebut bahwa seorang sahabat diminta menarik kembali pemberian kepada salah satu anaknya karena tidak adil. Q.S. Yusuf [12]: 100 menunjukkan bahwa setan merusak hubungan antar saudara. Karena itu hasad harus dikenali dan diobati, dan keadilan orang tua merupakan pencegahan yang penting.'},
{level:'HOTS',indicator:'Menganalisis hikmah ditundanya pertemuan keluarga Yakub',text:'Pertemuan keluarga Nabi Yakub dengan Yusuf terjadi setelah puluhan tahun berpisah. Analisis yang paling tepat terhadap hikmah penundaan tersebut adalah ...',options:['penundaan itu menyempurnakan nikmat dan memperbaiki diri saudara-saudaranya','penundaan itu menunjukkan bahwa ujian yang panjang tidak bermanfaat','penundaan itu berarti doa Yakub tidak dikabulkan dengan segera','penundaan itu tidak memiliki hikmah karena merupakan kebetulan'],answer:0,explanation:'Q.S. Yusuf [12]: 100 mencatat ucapan Yusuf ketika mempertemukan kedua orang tuanya bahwa ini merupakan tafsir mimpinya dahulu dan bahwa Allah telah menjadikannya kenyataan serta telah berbuat baik kepadanya. Q.S. Yusuf [12]: 90 mencatat pengakuan saudara-saudaranya bahwa Allah telah melebihkan Yusuf atas mereka dan bahwa mereka adalah orang yang bersalah. Q.S. Yusuf [12]: 52-53 mencatat pengakuan Yusuf bahwa Allah tidak mengabulkan tipu daya perempuan-perempuan itu dan bahwa nafsu selalu memerintahkan kejahatan. Q.S. Yusuf [12]: 111 menyebut bahwa pada kisah mereka terdapat pelajaran bagi orang-orang yang berakal. Hadis menyebut bahwa besarnya balasan sesuai dengan besarnya ujian. Karena itu penundaan itu menghasilkan kesempurnaan nikmat, perbaikan diri, dan pelajaran yang luas bagi umat.'},
{level:'HOTS',indicator:'Menentukan macam-macam sabar',text:'Para ulama membagi sabar menjadi tiga macam yaitu sabar dalam ketaatan, sabar dalam menjauhi maksiat, dan sabar dalam menghadapi musibah. Contoh yang paling tepat dari ketiga macam tersebut adalah ...',options:['menuntut ilmu dengan sungguh-sungguh, menahan diri dari bermain, dan menahan diri dari menangis','menunaikan zakat, menahan diri dari berbohong, dan menahan diri dari berobat','salat subuh ketika udara dingin, menahan diri dari menyontek, dan menerima kehilangan harta dengan lapang dada','menahan lapar ketika berpuasa, menahan diri dari tidur, dan menahan diri dari berkeluh kesah'],answer:2,explanation:'Sabar dalam ketaatan adalah menahan diri untuk terus melaksanakan perintah Allah walaupun terasa berat, dan contoh yang tepat adalah salat subuh ketika udara dingin karena menuntut perjuangan melawan keinginan tidur. Sabar dalam menjauhi maksiat adalah menahan diri dari perbuatan yang dilarang walaupun ada kesempatan dan dorongan, dan contoh yang tepat adalah menahan diri dari menyontek ketika kesempatan tersedia. Sabar dalam menghadapi musibah adalah menerima ketentuan Allah dengan lapang dada tanpa keluhan yang menunjukkan ketidakridaan, dan contoh yang tepat adalah menerima kehilangan harta. Q.S. al-Baqarah [2]: 45 memerintahkan memohon pertolongan dengan sabar dan salat. Hadis menyebut bahwa kesabaran itu pada pukulan pertama. Hadis juga menyebut bahwa Yusuf memilih penjara daripada maksiat sebagai contoh sabar dalam menjauhi maksiat.'},
{level:'HOTS',indicator:'Menganalisis kedudukan sabar dalam keimanan',text:'Rasulullah menyebut bahwa sabar merupakan separuh iman. Analisis yang paling tepat terhadap makna pernyataan tersebut adalah ...',options:['iman terdiri dari syukur atas nikmat dan sabar atas ujian','sabar lebih utama daripada seluruh rukun iman','sabar merupakan separuh iman karena yang lain dapat diperoleh tanpa usaha','sabar hanya diperlukan ketika tertimpa musibah'],answer:0,explanation:'Hadis menyebut bahwa sabar merupakan separuh iman dan bahwa iman terdiri dari syukur dan sabar. Hadis riwayat Muslim menyebut bahwa sungguh mengagumkan urusan orang beriman karena seluruh urusannya baik baginya, apabila memperoleh kesenangan ia bersyukur maka itu baik baginya, dan apabila tertimpa kesulitan ia bersabar maka itu baik baginya, dan hal itu tidak dimiliki oleh selain orang beriman. Q.S. al-Asr [103]: 3 menyebut saling menasihati dalam kebenaran dan saling menasihati dalam kesabaran sebagai ciri orang yang selamat dari kerugian. Q.S. az-Zumar [39]: 10 menyebut bahwa orang yang sabar akan diberi balasan tanpa perhitungan. Q.S. al-Baqarah [2]: 153 memerintahkan memohon pertolongan dengan sabar dan salat. Karena itu sabar mencakup seluruh keadaan hidup seorang mukmin dan merupakan separuh dari keimanannya.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika menghadapi kehilangan barang',text:'Seorang pelajar kehilangan sepeda yang digunakan untuk berangkat sekolah. Perilaku yang paling tepat adalah ...',options:['meratapi kehilangan itu berhari-hari sehingga tidak dapat belajar','mengucapkan istirja, berusaha mencari, dan tetap bersekolah','menyalahkan orang tua karena tidak menyediakan tempat penyimpanan yang aman','berhenti bersekolah sampai sepeda pengganti tersedia'],answer:1,explanation:'Q.S. al-Baqarah [2]: 155-157 menyebut bahwa manusia akan diuji dengan kekurangan harta dan jiwa, lalu memberi kabar gembira bagi orang yang sabar yaitu yang ketika tertimpa musibah mengucapkan sesungguhnya kami milik Allah dan kepada-Nya kami kembali, dan mereka memperoleh selawat dari Tuhan, rahmat, dan petunjuk. Hadis menyebut bahwa tidak ada suatu musibah pun yang menimpa seorang muslim melainkan Allah menghapus dosa-dosanya karena musibah itu. Hadis juga melarang meratap dan menyebut bahwa kesabaran itu pada pukulan pertama. Hadis menganjurkan mengikat kendaraan terlebih dahulu kemudian bertawakal, sehingga berusaha mencari dan melapor merupakan bagian dari ikhtiar. Hadis melarang menuduh tanpa bukti. Q.S. al-Baqarah [2]: 286 menegaskan bahwa Allah tidak membebani seseorang melainkan sesuai kesanggupannya.'},
{level:'HOTS',indicator:'Menganalisis hikmah ujian bagi orang beriman',text:'Rasulullah menyebut bahwa orang yang paling berat ujiannya adalah para nabi kemudian orang-orang saleh kemudian yang serupa dan yang serupa. Analisis yang paling tepat terhadap hikmah kenyataan tersebut adalah ...',options:['ujian berat berarti orang yang diuji memiliki banyak dosa sehingga harus disucikan','ujian berat merupakan tanda bahwa Allah membenci orang yang diuji','ujian berat mengangkat derajat dan menghapus dosa, bukan tanda kebencian','ujian berat hanya dialami oleh para nabi sehingga umat setelahnya tidak memperoleh keutamaan'],answer:2,explanation:'Hadis riwayat at-Tirmidzi dan Ibnu Majah menyebut bahwa manusia yang paling berat ujiannya adalah para nabi kemudian yang paling serupa dengan mereka kemudian yang paling serupa, dan seseorang diuji sesuai dengan kadar agamanya, apabila agamanya kuat maka ujiannya diperberat dan apabila agamanya tipis maka ujiannya diringankan, dan ujian itu terus menimpa seorang hamba hingga ia berjalan di muka bumi tanpa memiliki dosa. Hadis lain menyebut bahwa besarnya balasan sesuai dengan besarnya ujian dan bahwa Allah apabila mencintai suatu kaum maka Dia menguji mereka, sehingga barangsiapa ridha maka baginya keridhaan Allah dan barangsiapa marah maka baginya kemurkaan Allah. Q.S. al-Ankabut [29]: 2-3 menyebut bahwa manusia diuji agar diketahui siapa yang benar dan siapa yang dusta.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar dalam menuntut ilmu',text:'Perilaku yang paling tepat sebagai wujud sabar dalam menuntut ilmu adalah ...',options:['belajar dengan memaksakan diri sepanjang malam tanpa istirahat','belajar teratur walaupun berat dan tidak putus asa','berhenti belajar apabila merasa tidak mampu memahami','belajar hanya ketika akan menghadapi ujian'],answer:1,explanation:'Q.S. al-Mujadilah [58]: 11 menyebut bahwa Allah mengangkat derajat orang beriman dan orang yang diberi ilmu beberapa derajat. Hadis menyebut bahwa barangsiapa menempuh jalan untuk mencari ilmu maka Allah memudahkan baginya jalan menuju surga. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Q.S. al-Baqarah [2]: 286 menegaskan bahwa Allah tidak membebani seseorang melainkan sesuai kesanggupannya, sehingga memaksakan diri sepanjang malam tanpa istirahat bukan cara yang diajarkan. Hadis menyebut bahwa tubuh memiliki hak atas dirinya. Q.S. an-Nahl [16]: 43 memerintahkan bertanya kepada ahli pengetahuan apabila tidak mengetahui. Karena itu sabar dalam menuntut ilmu diwujudkan melalui keteraturan, keberlanjutan, kesabaran menghadapi kesulitan, dan keseimbangan dalam mengatur waktu.'},
{level:'HOTS',indicator:'Menganalisis bahaya mengeluh kepada manusia ketika tertimpa ujian',text:'Seseorang yang tertimpa ujian menceritakan penderitaannya kepada banyak orang dengan cara yang menunjukkan ketidakridaan terhadap ketentuan Allah. Analisis yang paling tepat terhadap bahaya perilaku tersebut adalah ...',options:['bahayanya hanya berupa rasa malu ketika keadaannya membaik','pahala sabar berkurang dan aib diri terbuka tanpa penyelesaian','bahayanya dapat dihilangkan dengan mengeluh kepada orang yang lebih menderita','tidak ada bahaya karena mengeluh merupakan cara melepaskan tekanan batin'],answer:1,explanation:'Q.S. Yusuf [12]: 86 mencatat ucapan Nabi Yakub bahwa ia hanya mengadukan kesusahan dan kesedihannya kepada Allah dan mengetahui dari Allah apa yang tidak mereka ketahui, yang menunjukkan bahwa tempat pengaduan yang benar adalah Allah. Hadis riwayat at-Tirmidzi menyebut bahwa barangsiapa mengadukan kesedihannya kepada manusia maka ia tidak tergolong orang yang sabar, dan dalam riwayat lain disebut bahwa mengadu kepada Allah merupakan bentuk kesabaran. Q.S. al-Baqarah [2]: 155-157 menyebut kabar gembira bagi orang yang sabar. Hadis menyebut bahwa kesabaran itu pada pukulan pertama. Q.S. ar-Rad [28]: 28 menegaskan bahwa hati menjadi tenteram dengan mengingat Allah. Hadis juga menyebut bahwa besarnya balasan sesuai dengan besarnya ujian. Karena itu mengeluh kepada manusia mengurangi pahala dan tidak menyelesaikan persoalan, sedangkan mengadu kepada Allah merupakan doa yang mendatangkan ketenangan.'},
{level:'HOTS',indicator:'Menentukan dalil naqli tentang pujian Allah kepada Nabi Ayyub',text:'Ayat yang memuji Nabi Ayyub sebagai orang yang sabar dan sebaik-baik hamba yang senantiasa kembali kepada Allah adalah ...',options:['Q.S. al-Anbiya [21]: 83','Q.S. Shad [38]: 44','Q.S. al-Baqarah [2]: 153','Q.S. Yusuf [12]: 90'],answer:1,explanation:'Q.S. Shad [38]: 44 berbunyi dan ambillah dengan tanganmu seikat rumput lalu pukullah dengan itu dan janganlah melanggar sumpah, sesungguhnya Kami dapati dia orang yang sabar, dialah sebaik-baik hamba, sesungguhnya dia amat taat kepada Tuhan. Ayat sebelumnya yaitu Q.S. Shad [38]: 41 menceritakan bahwa Ayyub diserang oleh setan dengan kepayahan dan azab, dan Q.S. Shad [38]: 42 berisi perintah menghentakkan kaki untuk memperoleh air. Adapun Q.S. al-Anbiya [21]: 83 berisi doa Ayyub ketika ditimpa bahaya, Q.S. Yusuf [12]: 90 berisi pengakuan saudara-saudara Yusuf bahwa Allah telah melebihkan Yusuf atas mereka, dan Q.S. al-Baqarah [2]: 153 berisi perintah memohon pertolongan dengan sabar dan salat. Karena itu Q.S. Shad [38]: 44 merupakan ayat yang secara langsung memuji kesabaran Nabi Ayyub.'},
{level:'HOTS',indicator:'Menganalisis kedudukan Yusuf ketika menolak mengungkit kesalahan saudaranya',text:'Ketika Yusuf menjelaskan keadaannya kepada saudara-saudaranya, ia menyebut bahwa setan telah merusak hubungan antara dia dan saudara-saudaranya. Analisis yang paling tepat terhadap pilihan kalimat tersebut adalah ...',options:['Yusuf menyebut setan karena tidak mengetahui siapa yang bersalah','memilih kalimat yang tidak mempermalukan saudara-saudaranya','Yusuf menyebut setan karena memang setan yang merencanakan perbuatan itu','Yusuf menyebut setan agar persoalannya dianggap selesai tanpa pertanggungjawaban'],answer:1,explanation:'Q.S. Yusuf [12]: 100 mencatat ucapan Yusuf bahwa ini merupakan tafsir mimpinya dahulu yang telah dijadikan kenyataan oleh Allah, dan bahwa Allah telah berbuat baik kepadanya ketika mengeluarkannya dari penjara dan membawa mereka dari dusun setelah setan merusak hubungan antara dia dan saudara-saudaranya, dan bahwa Tuhan Mahalembut terhadap apa yang dikehendaki-Nya serta Maha Mengetahui lagi Mahabijaksana. Q.S. Yusuf [12]: 92 mencatat bahwa Yusuf telah memaafkan mereka sebelumnya dan mendoakan ampunan bagi mereka. Hadis menyebut bahwa tidak ada yang memaafkan melainkan Allah menambah kemuliaannya. Q.S. al-Hujurat [49]: 12 melarang menyebut keburukan orang lain. Hadis juga menyebut bahwa barangsiapa menutupi aib seorang muslim maka Allah menutupi aibnya. Karena itu pilihan kalimat Yusuf merupakan adab tertinggi dalam memaafkan yaitu menjaga kehormatan orang yang pernah bersalah.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika diperlakukan tidak adil',text:'Seorang pelajar dituduh melakukan kesalahan yang tidak dilakukannya dan mendapat teguran dari guru. Perilaku yang paling tepat adalah ...',options:['menyimpan kekecewaan dan berhenti menghormati guru karena telah salah menilai','menyebarkan persoalan itu di media sosial agar memperoleh pembelaan','menjelaskan tenang disertai bukti dan tidak menyimpan dendam','membalas tuduhan itu dengan tuduhan terhadap teman yang dicurigai'],answer:2,explanation:'Q.S. Yusuf [12]: 33-34 menceritakan Yusuf yang dipenjara tanpa kesalahan lalu berdoa dan dipalingkan dari tipu daya, dan Q.S. Yusuf [12]: 50 menceritakan raja memerintahkan memeriksa perkara Yusuf sehingga kebenaran terungkap, yang menunjukkan bahwa menjelaskan kebenaran merupakan cara yang dibenarkan. Q.S. al-Baqarah [2]: 155-157 menyebut ujian dan kabar gembira bagi orang sabar. Hadis menyebut bahwa kesabaran itu pada pukulan pertama. Hadis juga menyebut bahwa barangsiapa mencari ridha Allah walaupun manusia marah maka Allah mencukupkannya dari urusan manusia. Q.S. an-Nisa [4]: 148 menyebut bahwa Allah tidak menyukai ucapan buruk yang diucapkan dengan terus terang kecuali oleh orang yang dizalimi, yang menunjukkan bahwa orang yang dizalimi boleh menyampaikan persoalannya kepada pihak yang berwenang. Menyebarkan persoalan di media sosial bukan cara yang tepat karena dapat menimbulkan fitnah yang lebih luas.'},
{level:'HOTS',indicator:'Menganalisis hikmah kisah Yusuf disebut sebagai sebaik-baik kisah',text:'Al-Quran menyebut kisah Yusuf sebagai sebaik-baik kisah. Analisis yang paling tepat terhadap alasan sebutan tersebut adalah ...',options:['sebutan itu karena kisah Yusuf tidak terdapat dalam kitab sebelumnya','kisahnya lengkap sehingga setiap keadaan menemukan pelajaran','sebutan itu berarti kisah para nabi lain kurang penting untuk dipelajari','sebutan itu karena kisah Yusuf merupakan kisah yang paling panjang dalam Al-Quran'],answer:1,explanation:'Q.S. Yusuf [12]: 3 menyebut bahwa Allah menceritakan kepada Nabi Muhammad sebaik-baik kisah melalui wahyu Al-Quran padahal sebelumnya beliau termasuk orang yang tidak mengetahui. Q.S. Yusuf [12]: 111 menyebut bahwa pada kisah para rasul terdapat pelajaran bagi orang-orang yang berakal dan bahwa Al-Quran bukan cerita yang dibuat-buat melainkan pembenar kitab sebelumnya, penjelasan segala sesuatu, serta petunjuk dan rahmat bagi orang beriman. Surah Yusuf merupakan satu-satunya surah yang menceritakan satu kisah secara lengkap dari awal hingga akhir tanpa terpotong oleh kisah lain. Kisah itu mencakup seluruh keadaan manusia yaitu anak yang dicemburui, orang yang digoda, orang yang dipenjara tanpa kesalahan, orang yang kehilangan anak, serta orang yang memperoleh kedudukan lalu memaafkan. Karena itu setiap orang dapat menemukan pelajaran yang sesuai dengan keadaannya.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika menghadapi ejekan',text:'Seorang pelajar diejek oleh teman-temannya karena keadaan keluarganya yang kurang mampu. Perilaku yang paling tepat adalah ...',options:['menjauhi seluruh teman dan tidak bergaul lagi','tidak membalas ejekan dan tetap menjaga kehormatan diri','menyampaikan ejekan itu kepada seluruh guru agar teman-temannya dihukum','membalas ejekan dengan ejekan yang lebih menyakitkan'],answer:1,explanation:'Q.S. al-Furqan [25]: 63 menggambarkan hamba Tuhan Yang Maha Pengasih yaitu yang berjalan di bumi dengan rendah hati dan apabila orang-orang jahil menyapa mereka, mereka mengucapkan kata-kata yang mengandung keselamatan. Q.S. al-Hujurat [49]: 11 melarang suatu kaum mengolok-olok kaum yang lain karena boleh jadi yang diolok-olok lebih baik dari yang mengolok-olok. Hadis menyebut bahwa tidak ada yang memaafkan melainkan Allah menambah kemuliaannya dan tidak ada yang bersikap tawadu karena Allah melainkan Allah mengangkat derajatnya. Q.S. al-Hujurat [49]: 13 menegaskan bahwa yang paling mulia di sisi Allah adalah yang paling bertakwa. Hadis juga menyebut bahwa Allah tidak melihat kepada rupa dan harta kalian melainkan kepada hati dan amal kalian. Karena itu membalas dengan serupa atau mengadu untuk menghukum bukan teladan, melainkan menjawab dengan keselamatan dan menjaga kehormatan diri.'},
{level:'HOTS',indicator:'Menganalisis hubungan sabar dengan salat',text:'Q.S. al-Baqarah [2]: 153 memerintahkan memohon pertolongan dengan sabar dan salat. Analisis yang paling tepat terhadap hubungan sabar dengan salat adalah ...',options:['sabar dan salat merupakan dua hal yang tidak berhubungan karena berbeda bidang','salat memberi kekuatan dan ketenangan untuk bersabar','salat merupakan pengganti sabar sehingga orang yang salat tidak perlu bersabar','salat hanya bermanfaat untuk memperoleh pahala bukan untuk menghadapi ujian'],answer:1,explanation:'Q.S. al-Baqarah [2]: 153 berbunyi wahai orang-orang yang beriman mohonlah pertolongan dengan sabar dan salat, sesungguhnya Allah beserta orang-orang yang sabar. Q.S. al-Baqarah [2]: 45 juga memerintahkan memohon pertolongan dengan sabar dan salat serta menyebut bahwa salat itu berat kecuali bagi orang yang khusyuk. Hadis menyebut bahwa Rasulullah apabila menghadapi persoalan yang berat maka beliau segera melaksanakan salat. Hadis juga menyebut bahwa Rasulullah salat malam hingga kaki beliau bengkak sebagai wujud syukur. Q.S. ar-Rad [28]: 28 menegaskan bahwa hati menjadi tenteram dengan mengingat Allah. Q.S. al-Ankabut [29]: 45 menyebut bahwa mengingat Allah merupakan perkara terbesar. Karena itu salat merupakan sarana memperoleh kekuatan batin untuk bersabar, dan sabar dalam melaksanakan salat merupakan bagian dari sabar dalam ketaatan.'},
{level:'HOTS',indicator:'Menentukan keteladanan istri Nabi Ayyub',text:'Istri Nabi Ayyub tetap mendampingi suaminya selama masa ujian yang panjang dan berkhidmat kepadanya dengan kesabaran. Keteladanan yang paling tepat dari sikap istri Nabi Ayyub adalah ...',options:['pendampingan dalam kesulitan merupakan ibadah bernilai besar','kesetiaan berarti menuruti seluruh keinginan pasangan walaupun salah','kesetiaan tidak memerlukan kesabaran karena merupakan kewajiban biasa','kesetiaan hanya dituntut dari istri ketika suami dalam keadaan baik'],answer:0,explanation:'Q.S. Shad [38]: 44 berisi perintah Allah kepada Ayyub untuk mengambil seikat rumput lalu memukulkannya sekali dan tidak melanggar sumpah, dan para mufasir menjelaskan bahwa keringanan itu diberikan karena istri Ayyub telah berkhidmat dan bersabar mendampingi suaminya selama masa ujian yang panjang. Q.S. ar-Rum [30]: 21 menyebut bahwa Allah menjadikan pasangan sebagai sumber ketenangan dan menjadikan kasih sayang di antara mereka. Q.S. al-Baqarah [2]: 187 menggambarkan hubungan suami istri dengan perumpamaan pakaian yang saling melindungi. Hadis menyebut bahwa sebaik-baik kalian adalah yang paling baik terhadap keluarganya. Q.S. al-Baqarah [2]: 153 memerintahkan memohon pertolongan dengan sabar. Karena itu kesetiaan dalam keadaan sulit merupakan bentuk ibadah yang bernilai besar dan menjadi sebab turunnya keringanan.'},
{level:'HOTS',indicator:'Menganalisis hikmah Yusuf menyembunyikan identitasnya dari saudara-saudaranya',text:'Nabi Yusuf mengetahui bahwa orang yang datang membeli bahan makanan adalah saudara-saudaranya, tetapi ia tidak segera memperkenalkan diri. Analisis yang paling tepat terhadap hikmah tindakan tersebut adalah ...',options:['menyusun rencana bijaksana agar saudara-saudaranya menyadari kesalahan','Yusuf menyembunyikan identitasnya karena takut dibalas oleh saudara-saudaranya','Yusuf menyembunyikan identitasnya karena masih menyimpan dendam','Yusuf menyembunyikan identitasnya karena jabatan melarangnya mengaku sebagai saudara pembeli biasa'],answer:0,explanation:'Q.S. Yusuf [12]: 58-62 menceritakan bahwa saudara-saudara Yusuf datang untuk membeli bahan makanan dan Yusuf mengenal mereka sedangkan mereka tidak mengenalnya, lalu Yusuf menyiapkan bahan makanan dan meminta agar mereka membawa saudara sebapak. Q.S. Yusuf [12]: 69-77 menceritakan rencana Yusuf sehingga Bunyamin ditahan di sisinya sesuai ketentuan hukum yang berlaku. Q.S. Yusuf [12]: 76 menyebut bahwa Allah mengangkat derajat siapa yang dikehendaki-Nya dan bahwa di atas setiap orang yang berilmu ada yang lebih mengetahui. Q.S. Yusuf [12]: 89-90 menceritakan ketika Yusuf akhirnya memperkenalkan diri dan saudara-saudaranya menyadari bahwa Allah telah melebihkannya atas mereka. Q.S. Yusuf [12]: 92 mencatat bahwa Yusuf memaafkan mereka. Karena itu penyembunyian identitas merupakan bagian dari rencana yang menghasilkan perbaikan batin saudara-saudaranya.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar dalam keluarga yang mengalami kesulitan ekonomi',text:'Sebuah keluarga mengalami kesulitan ekonomi sehingga anak-anaknya harus menyesuaikan diri dengan keadaan. Perilaku yang paling tepat adalah ...',options:['mengeluhkan keadaan kepada teman-teman agar memperoleh bantuan','menyembunyikan keadaan keluarga dari seluruh teman karena merasa malu','memahami keadaan orang tua, membantu, dan tetap belajar','menuntut orang tua mencari penghasilan tambahan walaupun membahayakan kesehatan'],answer:2,explanation:'Q.S. Yusuf [12]: 87 melarang berputus asa dari rahmat Allah dan menyebut bahwa yang berputus asa hanyalah kaum yang kafir. Q.S. at-Talaq [65]: 2-3 menyebut bahwa barangsiapa bertakwa kepada Allah maka Dia mengadakan baginya jalan keluar dan memberi rezeki dari arah yang tidak disangka. Q.S. al-Baqarah [2]: 286 menegaskan bahwa Allah tidak membebani seseorang melainkan sesuai kesanggupannya. Hadis menyebut bahwa orang yang memandang orang yang lebih rendah dalam urusan dunia tidak akan meremehkan nikmat Allah. Hadis juga menyebut bahwa sebaik-baik harta adalah yang digunakan untuk menafkahi keluarga. Q.S. al-Mujadilah [58]: 11 menyebut keutamaan ilmu. Karena itu memahami keadaan, membantu meringankan beban, tetap belajar, memperkuat doa dan usaha merupakan perilaku yang tepat, sedangkan mengeluh kepada teman atau menuntut hal yang membahayakan bukan penyelesaian.'},
{level:'HOTS',indicator:'Menganalisis kedudukan sabar sebagai sebab pertolongan Allah',text:'Q.S. al-Anfal [8]: 46 memerintahkan taat kepada Allah dan Rasul-Nya serta jangan berselisih yang menyebabkan kelemahan, dan bersabarlah karena Allah beserta orang-orang yang sabar. Analisis yang paling tepat terhadap hubungan sabar dengan kebersamaan Allah adalah ...',options:['kebersamaan khusus berupa pertolongan sehingga sabar menjadi sikap aktif','kesabaran tidak berhubungan dengan pertolongan karena pertolongan telah ditentukan','kebersamaan Allah hanya berlaku bagi para nabi yang sabar','kebersamaan Allah berarti Allah berada di tempat orang yang sabar'],answer:0,explanation:'Q.S. al-Anfal [8]: 46 berbunyi dan taatlah kepada Allah dan Rasul-Nya dan janganlah kamu berselisih yang menyebabkan kamu menjadi gentar dan hilang kekuatanmu, dan bersabarlah, sesungguhnya Allah beserta orang-orang yang sabar. Q.S. al-Baqarah [2]: 153 juga menyebut bahwa Allah beserta orang-orang yang sabar. Q.S. an-Nahl [16]: 96 menyebut bahwa apa yang di sisi Allah tidak akan habis dan bahwa Allah akan memberi balasan kepada orang yang sabar dengan balasan yang lebih baik dari apa yang telah mereka kerjakan. Q.S. az-Zumar [39]: 10 menyebut bahwa orang yang sabar akan diberi balasan tanpa perhitungan. Hadis menyebut bahwa pertolongan itu bersama kesabaran dan bahwa jalan keluar itu bersama kesusahan. Karena itu kebersamaan Allah merupakan pertolongan khusus yang menjadikan orang sabar mampu bertahan melampaui batas kemampuannya sendiri.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika menghadapi kegagalan',text:'Seorang pelajar gagal dalam seleksi yang telah dipersiapkannya dengan sungguh-sungguh. Perilaku yang paling tepat adalah ...',options:['menyalahkan panitia seleksi karena dianggap tidak adil','menerima dengan lapang dada, mengevaluasi, lalu mencoba lagi','menyimpan kekecewaan dan tidak menceritakan kepada siapa pun agar tidak terlihat lemah','berhenti mengikuti seleksi lain karena merasa tidak mampu'],answer:1,explanation:'Q.S. al-Baqarah [2]: 155-157 menyebut ujian dan memberi kabar gembira bagi orang yang sabar yaitu yang mengucapkan kalimat istirja ketika tertimpa musibah. Q.S. asy-Syarh [94]: 5-6 menyebut bahwa bersama kesulitan terdapat kemudahan. Q.S. al-Baqarah [2]: 216 menyebut bahwa boleh jadi manusia membenci sesuatu padahal sesuatu itu baik bagi mereka dan boleh jadi menyukai sesuatu padahal sesuatu itu buruk bagi mereka, sedangkan Allah mengetahui dan manusia tidak mengetahui. Hadis menyebut bahwa apabila seseorang tertimpa kegagalan maka jangan mengatakan seandainya aku melakukan demikian tentu hasilnya berbeda, karena ucapan seandainya membuka perbuatan setan. Q.S. al-Isra [17]: 84 memerintahkan berbuat sesuai cara masing-masing. Hadis juga menganjurkan mengikat kendaraan kemudian bertawakal. Karena itu evaluasi, perbaikan, dan usaha ulang disertai doa merupakan perilaku yang tepat.'},
{level:'HOTS',indicator:'Menganalisis hikmah kisah Nabi Ayyub bagi orang yang diuji dengan penyakit',text:'Kisah Nabi Ayyub memberikan pelajaran bagi orang yang sedang diuji dengan penyakit. Analisis yang paling tepat terhadap pelajaran tersebut adalah ...',options:['penyakit dapat mengangkat derajat dan berobat merupakan ikhtiar','pelajaran itu berarti orang yang sakit lebih mulia dari orang yang sehat','pelajaran itu hanya berlaku bagi orang yang saleh sehingga orang biasa tidak memperoleh keutamaan','pelajaran itu berarti penyakit tidak perlu diobati karena merupakan ujian yang harus diterima'],answer:0,explanation:'Q.S. al-Anbiya [21]: 83 mencatat doa Ayyub bahwa ia ditimpa bahaya dan Allah adalah Tuhan Yang Maha Penyayang, yang menunjukkan bahwa berdoa memohon kesembuhan bukan bentuk ketidakridaan. Q.S. al-Anbiya [21]: 84 mencatat bahwa Allah memperkenankan doanya dan menghilangkan bahaya yang menimpanya. Q.S. Shad [38]: 42 berisi perintah menghentakkan kaki untuk memperoleh air yang digunakan untuk mandi dan minum, yang merupakan bentuk ikhtiar pengobatan. Hadis menyebut bahwa Allah tidak menurunkan penyakit melainkan menurunkan pula obatnya. Hadis juga menyebut bahwa tidak ada musibah yang menimpa seorang muslim melainkan Allah menghapus dosanya karena musibah itu. Q.S. Yusuf [12]: 87 melarang berputus asa dari rahmat Allah. Karena itu penyakit dapat menjadi pengangkat derajat apabila diterima dengan sabar disertai doa dan ikhtiar pengobatan.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar dalam pergaulan dengan teman yang menyebalkan',text:'Seorang pelajar memiliki teman yang sering berbicara kasar dan merendahkan. Perilaku yang paling tepat adalah ...',options:['membalas kekasaran dengan kekasaran agar temannya menyadari','menceritakan keburukan temannya kepada teman lain agar memperoleh dukungan','memutuskan hubungan pertemanan tanpa penjelasan','bersabar tanpa membalas dan mengingatkan dengan bahasa baik'],answer:3,explanation:'Hadis menyebut bahwa seorang mukmin yang bergaul dengan masyarakat dan bersabar terhadap gangguan mereka lebih baik daripada mukmin yang tidak bergaul dan tidak bersabar terhadap gangguan mereka. Q.S. al-Furqan [25]: 63 menggambarkan orang yang apabila disapa oleh orang jahil mengucapkan kata yang mengandung keselamatan. Hadis menyebut bahwa tidak ada yang memaafkan melainkan Allah menambah kemuliaannya. Q.S. Fushshilat [41]: 34 menganjurkan menolak keburukan dengan cara yang lebih baik sehingga orang yang bermusuhan menjadi seperti teman yang setia. Q.S. al-Hujurat [49]: 12 melarang ghibah dan berprasangka buruk. Hadis juga menyebut bahwa agama adalah nasihat. Karena itu bersabar tanpa membalas, mengingatkan dengan baik, dan membatasi pergaulan apabila merugikan merupakan cara yang seimbang, berbeda dari memutus hubungan tanpa penjelasan atau menceritakan keburukan teman.'},
{level:'HOTS',indicator:'Menganalisis hikmah kisah keluarga Yakub tentang keadilan orang tua',text:'Kisah keluarga Nabi Yakub menunjukkan bahwa kecenderungan hati kepada salah satu anak dapat menimbulkan hasad pada anak yang lain. Analisis yang paling tepat terhadap pelajaran bagi orang tua adalah ...',options:['orang tua perlu adil dalam perlakuan yang tampak','orang tua sebaiknya menyembunyikan kecintaannya kepada seluruh anak agar tidak ada yang merasa istimewa','kecenderungan hati orang tua tidak berpengaruh sehingga tidak perlu diatur','orang tua tidak boleh mencintai salah satu anak lebih dari yang lain sehingga harus membagi perhatian secara sama persis'],answer:0,explanation:'Q.S. Yusuf [12]: 8 mencatat bahwa hasad saudara-saudara Yusuf timbul dari perasaan bahwa Yusuf dan saudaranya lebih dicintai oleh ayah mereka. Q.S. Yusuf [12]: 67 juga mencatat bahwa Yakub menasihati anak-anaknya agar tidak masuk dari satu pintu melainkan dari pintu-pintu yang berbeda, yang menunjukkan kehati-hatian dan perhatian seorang ayah. Hadis menyebut bahwa Rasulullah memerintahkan berlaku adil di antara anak-anak dalam pemberian dan menyebut bahwa seorang sahabat diminta menarik kembali pemberian kepada salah satu anaknya karena tidak adil. Hadis juga menyebut bahwa Allah menyukai apabila seseorang berlaku adil di antara anak-anaknya. Para ulama menjelaskan bahwa keadilan yang dituntut adalah dalam hal yang tampak seperti nafkah, pemberian, dan perlakuan, sedangkan perasaan hati tidak sepenuhnya dikuasai oleh manusia.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika menghadapi ujian berturut-turut',text:'Seorang pelajar mengalami beberapa ujian dalam waktu berdekatan yaitu kehilangan barang, nilai yang tidak memuaskan, dan masalah dalam keluarga. Perilaku yang paling tepat adalah ...',options:['menghadapi satu per satu dan tetap menunaikan kewajiban','menyerah dan berhenti berusaha karena ujian terlalu banyak','membandingkan keadaannya dengan keadaan teman yang lebih baik agar menyadari kekurangannya','menunda seluruh persoalan hingga keadaan membaik dengan sendirinya'],answer:0,explanation:'Q.S. asy-Syarh [94]: 5-6 menyebut bahwa bersama kesulitan terdapat kemudahan dan bahwa bersama kesulitan terdapat kemudahan, yang diulang dua kali untuk menegaskan bahwa setiap kesulitan pasti disertai kemudahan. Q.S. al-Baqarah [2]: 286 menegaskan bahwa Allah tidak membebani seseorang melainkan sesuai kesanggupannya. Hadis menyebut bahwa besarnya balasan sesuai dengan besarnya ujian dan bahwa ujian terus menimpa seorang hamba hingga ia berjalan di muka bumi tanpa dosa. Hadis juga menyebut bahwa pertolongan itu bersama kesabaran. Q.S. Yusuf [12]: 87 melarang berputus asa dari rahmat Allah. Hadis menganjurkan meminta bantuan dan bermusyawarah dalam persoalan penting. Q.S. al-Baqarah [2]: 153 memerintahkan memohon pertolongan dengan sabar dan salat. Hadis memerintahkan memandang orang yang lebih rendah dalam urusan dunia, bukan membandingkan dengan yang lebih baik yang justru menambah kesedihan.'},
{level:'HOTS',indicator:'Menganalisis hikmah kisah Yusuf bagi orang yang dipenjara atau tertuduh',text:'Kisah Nabi Yusuf memberikan pelajaran bagi orang yang berada dalam keadaan tertuduh atau terpenjara tanpa kesalahan. Analisis yang paling tepat terhadap pelajaran tersebut adalah ...',options:['kebenaran terungkap pada waktunya dan tetap bermanfaat di tempatnya','pelajaran itu berarti orang yang tertuduh tidak akan memperoleh keadilan','pelajaran itu hanya berlaku bagi orang yang tidak bersalah sama sekali','pelajaran itu berarti keadaan tertuduh harus diterima tanpa usaha membela diri'],answer:0,explanation:'Q.S. Yusuf [12]: 36-41 menceritakan bahwa Yusuf di penjara menyampaikan dakwah kepada kedua temannya dan menjelaskan tafsir mimpi mereka, sehingga penjara menjadi tempat memberi manfaat. Q.S. Yusuf [12]: 50-52 menceritakan raja memerintahkan memeriksa perkara Yusuf sehingga kebenaran terungkap dan perempuan-perempuan mengakui bahwa Yusuf tidak berbuat salah. Q.S. Yusuf [12]: 54 mencatat bahwa Yusuf diangkat menjadi bendahara negeri karena ia orang yang dapat dipercaya dan berilmu. Hadis menganjurkan menjelaskan kebenaran melalui jalur yang tepat dan melarang diam ketika dizalimi. Q.S. an-Nisa [4]: 148 menyebut bahwa Allah tidak menyukai ucapan buruk yang diucapkan dengan terus terang kecuali oleh orang yang dizalimi. Karena itu pelajaran dari kisah Yusuf mencakup kesabaran, tetap memberi manfaat, ikhtiar menjelaskan kebenaran, dan harapan akan kedudukan yang baik setelah masa sulit.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika menghadapi orang yang berutang tidak membayar',text:'Seorang pelajar meminjamkan uang tabungannya kepada temannya dan temannya tidak segera mengembalikan. Perilaku yang paling tepat adalah ...',options:['tidak menagih sama sekali karena menagih dianggap tidak ikhlas','menagih dengan ancaman agar temannya segera membayar','menagih dengan baik dan memberi tambahan waktu bila sulit','menyebarkan persoalan itu agar teman lain tidak meminjamkan uang kepadanya'],answer:2,explanation:'Q.S. al-Baqarah [2]: 280 menganjurkan memberi tambahan waktu kepada orang yang berutang apabila ia dalam kesulitan, dan menyebut bahwa menyedekahkan utang itu lebih baik apabila mengetahui. Q.S. al-Baqarah [2]: 283 menyebut perintah menyampaikan amanah kepada pemiliknya, sehingga menagih merupakan hak yang boleh digunakan. Hadis menyebut bahwa menunda pembayaran utang oleh orang yang mampu merupakan bentuk kezaliman. Hadis juga menyebut bahwa barangsiapa memberi tambahan waktu kepada orang yang kesulitan atau membebaskan utangnya maka Allah akan menaunginya pada hari yang tidak ada naungan kecuali naungan-Nya. Hadis melarang mengambil harta orang lain tanpa kerelaannya. Hadis juga menganjurkan menuntut hak dengan cara yang baik tanpa menyakiti. Karena itu menagih dengan cara baik, memberi tambahan waktu apabila diperlukan, dan tidak mengambil barang tanpa izin merupakan perilaku yang tepat.'},
{level:'HOTS',indicator:'Menganalisis hikmah kisah Yusuf tentang rencana manusia dan rencana Allah',text:'Saudara-saudara Yusuf merencanakan keburukan, istri pejabat merencanakan godaan, dan Yusuf dipenjara, tetapi seluruh peristiwa itu berakhir dengan kedudukan Yusuf yang tinggi dan keluarga yang bersatu. Analisis yang paling tepat terhadap hikmah kenyataan tersebut adalah ...',options:['hikmahnya bahwa rencana manusia tidak berpengaruh sehingga tidak perlu berhati-hati','hikmahnya bahwa kebaikan selalu kalah pada awalnya dan menang pada akhirnya','hikmahnya bahwa rencana jahat manusia selalu berhasil pada akhirnya','Allah mengubah rencana buruk manusia menjadi kebaikan lebih besar'],answer:3,explanation:'Q.S. Yusuf [12]: 99-100 mencatat ucapan Yusuf kepada saudara-saudaranya bahwa tidak ada cercaan pada hari ini dan bahwa Allah telah menjadikannya kenyataan dari mimpi yang dahulu. Q.S. Ali Imran [3]: 54 menyebut bahwa orang kafir merencanakan dan Allah juga merencanakan, dan Allah merupakan sebaik-baik perencana. Q.S. at-Talaq [65]: 2-3 menyebut bahwa barangsiapa bertakwa kepada Allah maka Dia mengadakan baginya jalan keluar dan memberi rezeki dari arah yang tidak disangka. Q.S. Yusuf [12]: 52 mencatat pengakuan bahwa Allah tidak mengabulkan tipu daya orang yang berencana jahat. Hadis menyebut bahwa besarnya balasan sesuai dengan besarnya ujian. Karena itu hikmah kisah Yusuf menegaskan bahwa rencana Allah melampaui rencana manusia dan bahwa kesabaran dalam menghadapi rencana jahat menghasilkan kedudukan yang tidak dapat dicapai melalui usaha manusia sendiri.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika menunggu hasil usaha yang lama',text:'Seorang pelajar telah berusaha keras selama setahun untuk memperoleh prestasi tertentu tetapi hasilnya belum terlihat. Perilaku yang paling tepat adalah ...',options:['berhenti berusaha karena usaha itu tidak menghasilkan apa pun','menyalahkan keadaan dan orang lain sebagai penyebab kegagalannya','tetap berusaha sambil memperbaiki cara yang digunakan','mengeluh kepada seluruh orang agar memperoleh simpati dan dukungan'],answer:2,explanation:'Q.S. an-Najm [53]: 39-41 menyebut bahwa manusia tidak memperoleh melainkan apa yang telah diusahakannya dan bahwa usahanya akan diperlihatkan kemudian lalu diberi balasan yang paling sempurna, sehingga usaha tidak pernah sia-sia. Q.S. al-Ankabut [29]: 69 menyebut bahwa orang yang bersungguh-sungguh di jalan Allah akan ditunjukkan jalan-jalan-Nya. Hadis menyebut bahwa pertolongan itu bersama kesabaran dan bahwa jalan keluar itu bersama kesusahan. Q.S. at-Talaq [65]: 2-3 menyebut bahwa barangsiapa bertakwa kepada Allah maka Dia mengadakan baginya jalan keluar. Hadis juga menganjurkan bermusyawarah dan meminta nasihat. Q.S. Yusuf [12]: 87 melarang berputus asa dari rahmat Allah. Karena itu tetap berusaha sambil memperbaiki cara, berdoa, mencari nasihat, dan meyakini bahwa usaha tidak sia-sia merupakan perilaku yang tepat.'},
{level:'HOTS',indicator:'Menganalisis kedudukan sabar sebagai amal tanpa batas perhitungan',text:'Q.S. az-Zumar [39]: 10 menyebut bahwa orang yang sabar akan diberi balasan tanpa perhitungan. Analisis yang paling tepat terhadap makna balasan tanpa perhitungan adalah ...',options:['makna itu berarti sabar merupakan amal yang paling mudah sehingga balasannya besar','makna itu berarti sabar lebih utama daripada salat dan puasa','makna itu hanya berlaku bagi sabar dalam menghadapi musibah besar','balasan sabar tidak dibatasi perhitungan sehingga tanpa batas'],answer:3,explanation:'Q.S. az-Zumar [39]: 10 berbunyi katakanlah wahai hamba-hamba-Ku yang beriman bertakwalah kepada Tuhanmu, bagi orang-orang yang berbuat baik di dunia ini memperoleh kebaikan, dan bumi Allah itu luas, sesungguhnya hanya orang-orang yang bersabarlah yang dicukupkan pahala mereka tanpa batas. Q.S. al-Baqarah [2]: 261 menyebut bahwa sedekah dilipatgandakan hingga tujuh ratus kali, yang menunjukkan bahwa amal lain memiliki kelipatan tertentu. Hadis menyebut bahwa sabar merupakan separuh iman. Q.S. al-Baqarah [2]: 155-157 menyebut ujian dan kabar gembira bagi orang sabar. Hadis juga menyebut bahwa besarnya balasan sesuai dengan besarnya ujian. Para ulama menjelaskan bahwa sabar mencakup tiga macam yaitu sabar dalam ketaatan, sabar dalam menjauhi maksiat, dan sabar dalam menghadapi musibah, sehingga sabar menyertai seluruh keadaan hidup seorang mukmin dan karenanya balasannya tidak dibatasi.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika menghadapi orang tua yang keras',text:'Seorang pelajar memiliki orang tua yang keras dalam mendidik dan sering memarahinya. Perilaku yang paling tepat adalah ...',options:['membalas kemarahan orang tua agar dianggap setara','menjaga jarak dengan orang tua agar tidak sering dimarahi','menceritakan kekerasan orang tua kepada teman-teman agar memperoleh dukungan','bersabar, tidak membantah, dan menyampaikan perasaan dengan lembut'],answer:3,explanation:'Q.S. Luqman [31]: 15 menyebut bahwa apabila orang tua memaksa kepada syirik maka jangan menaati keduanya, tetapi tetap pergaulilah keduanya di dunia dengan baik, yang menunjukkan bahwa walaupun terdapat persoalan besar maka adab terhadap orang tua tetap dijaga. Q.S. al-Isra [17]: 23 melarang mengucapkan kata ah dan membentak orang tua serta memerintahkan mengucapkan perkataan yang mulia. Q.S. al-Isra [17]: 24 memerintahkan merendahkan sayap kehinaan karena kasih sayang dan berdoa bagi keduanya. Hadis menyebut bahwa ridha Allah berada pada ridha orang tua. Hadis juga menyebut bahwa seorang mukmin yang bergaul dengan masyarakat dan bersabar terhadap gangguan mereka lebih baik daripada yang tidak bergaul. Hadis menganjurkan menyampaikan perasaan dengan cara yang lembut dan tidak menyakiti. Karena itu menjaga jarak atau menceritakan kekerasan orang tua kepada teman bukan perilaku yang tepat.'},
{level:'HOTS',indicator:'Menganalisis hikmah ujian Nabi Ayyub yang berlangsung lama',text:'Ujian Nabi Ayyub berlangsung dalam waktu yang sangat lama, berbeda dari ujian yang segera berakhir. Analisis yang paling tepat terhadap hikmah ujian yang berlangsung lama adalah ...',options:['ujian yang lama tidak memiliki hikmah karena merupakan ketentuan yang harus diterima','ujian lama menghasilkan kesabaran dan pahala yang lebih besar','ujian yang lama berarti Ayyub memiliki dosa yang sangat banyak','ujian yang lama berarti doa Ayyub tidak dikabulkan'],answer:1,explanation:'Q.S. Shad [38]: 44 menyebut pujian Allah bahwa Allah mendapati Ayyub sebagai orang yang sabar dan sebaik-baik hamba yang senantiasa kembali kepada Allah, yang menunjukkan bahwa masa ujian yang panjang menghasilkan kedudukan yang tinggi. Hadis menyebut bahwa besarnya balasan sesuai dengan besarnya ujian dan bahwa ujian terus menimpa seorang hamba hingga ia berjalan di muka bumi tanpa dosa. Hadis juga menyebut bahwa manusia yang paling berat ujiannya adalah para nabi kemudian yang paling serupa dengan mereka. Q.S. al-Anbiya [21]: 84 mencatat bahwa Allah memperkenankan doa Ayyub pada waktu yang ditetapkan-Nya. Q.S. al-Baqarah [2]: 216 menyebut bahwa manusia boleh jadi membenci sesuatu padahal sesuatu itu baik bagi mereka. Karena itu ujian yang lama menghasilkan kesabaran yang lebih tinggi, pahala yang lebih besar, dan teladan yang lebih kuat bagi umat.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika menghadapi penyakit anggota keluarga',text:'Anggota keluarga seorang pelajar menderita penyakit yang memerlukan perawatan panjang. Perilaku yang paling tepat adalah ...',options:['mengabaikan kewajiban belajar karena seluruh waktu digunakan untuk merawat','membantu perawatan sesuai kemampuan dan tetap menunaikan kewajiban','menceritakan keadaan keluarga kepada teman-teman agar memperoleh bantuan secara terus-menerus','menyerahkan seluruh perawatan kepada rumah sakit karena bukan bidangnya'],answer:1,explanation:'Q.S. al-Isra [17]: 23-24 memerintahkan berbuat baik kepada orang tua terutama ketika mencapai usia lanjut, yang mencakup perawatan. Hadis menyebut bahwa sebaik-baik kalian adalah yang paling baik terhadap keluarganya. Q.S. al-Baqarah [2]: 286 menegaskan bahwa Allah tidak membebani seseorang melainkan sesuai kesanggupannya, sehingga membantu perawatan dilakukan sesuai kemampuan tanpa mengabaikan kewajiban lain. Hadis menyebut bahwa Allah tidak menurunkan penyakit melainkan menurunkan pula obatnya, sehingga mencari pengobatan merupakan ikhtiar. Hadis juga melarang berputus asa. Q.S. al-Baqarah [2]: 153 memerintahkan memohon pertolongan dengan sabar dan salat. Hadis menyebut bahwa orang yang mengadukan kesedihannya kepada manusia tidak tergolong orang yang sabar, sehingga menceritakan keadaan untuk memperoleh bantuan secara terus-menerus bukan cara yang tepat kecuali dalam keadaan benar-benar memerlukan dan melalui jalur yang layak.'},
{level:'HOTS',indicator:'Menganalisis hubungan kisah Nabi Ayyub dan Nabi Yakub dalam satu materi',text:'Kisah ketabahan Nabi Ayyub dan kisah keluarga Nabi Yakub dipelajari dalam satu materi. Analisis yang paling tepat terhadap keterkaitan kedua kisah tersebut adalah ...',options:['keduanya merupakan kisah tentang hasad antar saudara','keduanya merupakan kisah tentang kehilangan harta','keduanya teladan sabar dalam dua bentuk ujian berbeda','keterkaitan keduanya hanya karena terjadi pada masa yang berdekatan'],answer:2,explanation:'Q.S. al-Anbiya [21]: 83-84 menceritakan ujian Nabi Ayyub pada dirinya berupa bahaya yang menimpa badan serta kehilangan harta dan anak, lalu dipulihkan oleh Allah. Q.S. Yusuf [12]: 84-87 menceritakan ujian Nabi Yakub berupa kehilangan anak yang paling dicintainya dalam waktu lama sehingga matanya menjadi putih karena kesedihan, tetapi ia tetap berharap kepada Allah dan melarang anak-anaknya berputus asa. Hadis menyebut bahwa manusia yang paling berat ujiannya adalah para nabi kemudian yang paling serupa dengan mereka. Q.S. al-Baqarah [2]: 155-157 menyebut bentuk ujian berupa ketakutan, kelaparan, kekurangan harta, jiwa, dan buah-buahan, yang mencakup ujian pada diri sendiri dan ujian melalui orang yang dicintai. Hadis juga menyebut bahwa besarnya balasan sesuai dengan besarnya ujian. Karena itu kedua kisah merupakan teladan untuk dua bentuk ujian yang keduanya mungkin dialami oleh setiap orang.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika hasil kebaikan tidak dihargai',text:'Seorang pelajar membantu membersihkan kelas setiap hari tetapi tidak ada yang menghargai dan bahkan ada yang mengotorinya kembali. Perilaku yang paling tepat adalah ...',options:['berhenti membantu karena usahanya tidak dihargai','melaporkan seluruh teman kepada guru agar mereka dihukum','tetap berbuat baik dengan niat untuk Allah bukan penghargaan','menyindir teman yang mengotori kelas di depan umum agar jera'],answer:2,explanation:'Q.S. al-Lail [92]: 18-20 menggambarkan orang yang menafkahkan hartanya untuk menyucikan diri tanpa ada seorang pun yang memberi nikmat kepadanya yang harus dibalas, melainkan semata-mata mengharapkan wajah Tuhannya, yang menunjukkan bahwa amal ikhlas tidak bergantung pada penghargaan manusia. Hadis qudsi menyebut bahwa Allah Maha Cukup dari sekutu sehingga amal yang dikerjakan untuk Allah dan untuk selain-Nya ditolak. Hadis menyebut bahwa barangsiapa mencari ridha Allah walaupun manusia marah maka Allah mencukupkannya dari urusan manusia. Hadis juga menyebut bahwa menyingkirkan gangguan dari jalan merupakan cabang iman. Hadis menganjurkan menasihati secara pribadi bukan di depan umum karena nasihat di depan umum terasa seperti penghinaan. Hadis juga menyebut bahwa seorang mukmin yang bergaul dan bersabar terhadap gangguan lebih baik daripada yang tidak bergaul. Karena itu berhenti berbuat baik atau menyindir di depan umum bukan perilaku yang tepat.'},
{level:'HOTS',indicator:'Menganalisis hikmah kisah Yusuf mengajarkan penjagaan diri dari godaan',text:'Kisah Yusuf mencakup godaan yang sangat berat ketika pintu-pintu telah ditutup dan ajakan datang dari perempuan yang berkedudukan. Analisis yang paling tepat terhadap hikmah pencantuman peristiwa itu dalam Al-Quran adalah ...',options:['peristiwa itu dicantumkan untuk menunjukkan kelemahan manusia dalam menghadapi godaan','peristiwa itu dicantumkan untuk menunjukkan bahwa Yusuf hampir berbuat salah','peristiwa itu dicantumkan tanpa hikmah tertentu karena merupakan bagian dari rangkaian kisah','mengajarkan cara menjaga diri dari godaan dan segera meninggalkannya'],answer:3,explanation:'Q.S. Yusuf [12]: 23-24 menceritakan godaan tersebut dan mencatat jawaban Yusuf yaitu aku berlindung kepada Allah, sungguh tuanku telah memperlakukan aku dengan baik, dan sesungguhnya orang yang zalim tidak akan beruntung, serta menyebut bahwa Allah memalingkan dari padanya keburukan dan kekejian karena ia termasuk hamba-hamba yang terpilih. Q.S. Yusuf [12]: 25 menceritakan keduanya berlomba menuju pintu, yang menunjukkan usaha meninggalkan tempat godaan. Q.S. Yusuf [12]: 33 mencatat doa Yusuf bahwa penjara lebih ia sukai daripada memenuhi ajakan mereka, dan jika Allah tidak menghindarkan tipu daya mereka tentu ia akan cenderung memenuhi keinginan mereka. Q.S. Yusuf [12]: 34 menyebut bahwa Allah memperkenankan doanya. Hadis menyebut bahwa salah satu golongan yang dinaungi Allah adalah laki-laki yang diajak oleh perempuan berkedudukan lalu berkata aku takut kepada Allah. Karena itu peristiwa itu mengajarkan cara menjaga diri dari godaan melalui zikir, ingat nikmat, kesadaran akan akibat kezaliman, meninggalkan tempat godaan, dan doa.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika menghadapi ejekan karena beribadah',text:'Seorang pelajar diejek oleh teman-temannya karena selalu melaksanakan salat tepat waktu di sekolah. Perilaku yang paling tepat adalah ...',options:['mengurangi ibadahnya agar tidak diejek lagi','tetap istiqamah beribadah dan menjawab ejekan dengan tenang','membalas ejekan dengan ejekan terhadap ibadah teman yang kurang','berhenti beribadah di sekolah dan beribadah hanya di rumah'],answer:1,explanation:'Q.S. al-Maun [107]: 1-2 menggambarkan orang yang mendustakan agama dan Q.S. al-Humazah [104]: 1 mengecam orang yang mengumpat dan mencela, sehingga mengejek orang yang beribadah merupakan perilaku yang tercela. Q.S. al-Furqan [25]: 63 menggambarkan orang yang apabila disapa oleh orang jahil mengucapkan kata yang mengandung keselamatan. Hadis menyebut bahwa istiqamah merupakan amal yang paling dicintai Allah walaupun sedikit. Hadis juga menyebut bahwa barangsiapa mencari ridha Allah walaupun manusia marah maka Allah mencukupkannya dari urusan manusia. Hadis melarang merasa sombong dengan amal dan menyebut bahwa tidak akan masuk surga orang yang di dalam hatinya terdapat kesombongan sebesar biji sawi. Hadis menganjurkan berdakwah dengan cara yang baik dan tidak menggurui. Hadis juga menyebut bahwa agama seseorang mengikuti agama sahabat karibnya, sehingga tetap bergaul dan mendoakan merupakan cara yang lebih baik daripada berhenti beribadah di sekolah.'},
{level:'HOTS',indicator:'Menganalisis hikmah kisah Yakub yang matanya menjadi putih karena kesedihan',text:'Q.S. Yusuf [12]: 84 menyebut bahwa mata Nabi Yakub menjadi putih karena kesedihan yang mendalam dan bahwa ia menahan amarah. Analisis yang paling tepat terhadap hikmah ayat tersebut adalah ...',options:['kesedihan manusiawi selama tidak menimbulkan ketidakridaan kepada Allah','ayat itu menunjukkan bahwa Yakub tidak sabar karena matanya rusak','ayat itu menunjukkan bahwa bersedih merupakan perbuatan yang dilarang','ayat itu berarti kesedihan yang dalam selalu merusak kesehatan sehingga harus dihindari dengan melupakan persoalannya'],answer:0,explanation:'Q.S. Yusuf [12]: 84 berbunyi dan ia berpaling dari mereka sambil berkata alangkah besar duka citaku terhadap Yusuf, dan kedua matanya menjadi putih karena kesedihan yang mendalam dan ia adalah orang yang menahan amarahnya. Q.S. Yusuf [12]: 86 mencatat bahwa ia hanya mengadukan kesusahan dan kesedihannya kepada Allah. Hadis menyebut bahwa Rasulullah meneteskan air mata ketika putranya Ibrahim wafat, lalu bersabda bahwa mata meneteskan air mata dan hati bersedih tetapi kami tidak mengucapkan kecuali apa yang diridhai Tuhan kami. Hadis melarang meratap, memukul pipi, dan merobek pakaian ketika tertimpa musibah, yang merupakan bentuk kesedihan yang melampaui batas. Q.S. al-Baqarah [2]: 155-157 menyebut kabar gembira bagi orang yang sabar. Karena itu kesedihan merupakan perasaan manusiawi yang tidak dilarang selama tidak melampaui batas dan tidak menimbulkan ketidakridaan terhadap ketentuan Allah.'}
]});
